item.content:encoded:
/* Side menu CSS */

@media (min-width: 769px) {
	body {
		padding-left: 60px;
	}
}

#site-navigation {
	position: fixed;
	left: 0;
	min-height: 100vh;
	max-width: 60px;
	overflow: hidden;
}

#site-navigation .inside-navigation {
	flex-direction: column;
	flex-wrap: nowrap;
	min-height: 100vh;
}

.admin-bar #site-navigation .inside-navigation {
	min-height: calc(100vh - 32px);
}

#site-navigation .navigation-branding {
    transform: rotate(90deg);
    display: block;
    height: 100%;
    margin: 30px 0 auto;
}

#content {
	padding: 40px;
}

#main,
.sidebar > .inside-right-sidebar,
.sidebar > .inside-left-sidebar{
	margin-top: 0;
	margin-bottom: 0;
}

#site-navigation .main-nav > ul {
	flex-direction: column;
}

.menu-bar-items {
	order: -10;
}

#site-navigation .rotate {
	transform: rotate(90deg);
	margin-bottom: auto;
	white-space: nowrap;
}

@media (max-width: 768px) {
	#site-navigation .menu-toggle {
		display: none;
	}
}

.site-footer {
  padding: 0 40px;
}

/* Narrow content */

.no-sidebar .inside-article > *,
.no-sidebar #comments,
.no-sidebar .nav-links {
	max-width: 700px;
	margin-left: auto;
	margin-right: auto;
}

.nav-links > * {
		padding: 5px 15px;
    border-width: 1px;
    border-style: solid;
    border-color: inherit;
}

.separate-containers .page-header {
	background: transparent;
	text-align: center;
	padding-top: 20px;
	padding-bottom: 20px;
}

/* Slideout navigation */
#generate-slideout-menu .main-nav {
	padding-bottom: 20px;
	border-bottom: 1px solid rgba(0,0,0,0.1);
}

.slideout-navigation .rpwwt-widget:after {
    display: table;
    content: "";
    clear: both;
}

.slideout-navigation .rpwwt-widget ul li img {
	margin: 0 10px 0 0;
}

.slideout-navigation .rpwwt-widget ul li {
	margin-bottom: 10px
}

.slideout-navigation .slideout-widget {
	margin-top: 30px;
}

.slideout-widget .widget-title {
	margin-bottom: 15px;
}

.slideout-navigation .fa {
	padding-right: 5px;
}

.slideout-navigation .fa-facebook-square {
	color: #3b5998;
}

.slideout-navigation .fa-twitter-square {
	color: #00aced;
}

.slideout-navigation .fa-instagram {
	color: #c32aa3;
}
